-- Nog vijf lange duurritten in de workout-bibliotheek: kracht (lage cadans),
-- souplesse (hoge cadans), cadanswissel, golvend en "alles kan". Zelfde opzet
-- als 0227; de onderbouwing staat in docs/lange-ritten-variatie.md.
--
-- Cadans staat in de notitie van een blok: een blok heeft er geen eigen veld
-- voor, en intervals.icu krijgt hem dus niet als doel mee.

insert into public.training_workout_templates
  (form, title, description, duration_minutes, intensity, target_type, structure_json, is_standard)
select
  v.form, v.title, v.description, v.duration_minutes, v.intensity, v.target_type, v.structure_json, true
